package witchinggadgets;
import thaumcraft.aspect.Aspect;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.phys.AABB;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(WitchingGadgets.ID) @PrefixGameTestTemplate(false)
public final class Port5Tests {
    @GameTest(template="test/platform") public static void eastFaceDefinesOutput(GameTestHelper h){faceOutput(h,Direction.EAST);}
    @GameTest(template="test/platform") public static void northFaceDefinesOutput(GameTestHelper h){faceOutput(h,Direction.NORTH);}
    @GameTest(template="test/platform") public static void southFaceDefinesOutput(GameTestHelper h){faceOutput(h,Direction.SOUTH);}
    static void faceOutput(GameTestHelper h,Direction face){var local=IntegrationGameTests.furnace(h);var p=h.makeMockPlayer(GameType.CREATIVE);p.setYRot(face.toYRot()+90);h.assertTrue(Multiblock.tryForm(h.getLevel(),h.absolutePos(local.relative(face)),p,new ItemStack(Content.tc("wand")),face),"formation failed");MachineEntity root=h.getBlockEntity(local);h.assertTrue(root.facing()==face,"exit did not save "+face);root.blastEmit(new ItemStack(Items.IRON_INGOT,3));var out=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(root.getBlockPos()).inflate(3),e->e.getItem().is(Items.IRON_INGOT)).getFirst();var delta=out.position().subtract(root.getBlockPos().getCenter());h.assertTrue(delta.x*face.getStepX()+delta.z*face.getStepZ()>1.5,"item appeared on wrong side");h.assertTrue(out.getDeltaMovement().x*face.getStepX()+out.getDeltaMovement().z*face.getStepZ()>0,"velocity points away from saved face");h.succeed();}
    @GameTest(template="test/platform") public static void roseLightingNeverQueriesLiveWorld(GameTestHelper h){var block=(MachineBlock)Content.block("rose_vines");var state=block.defaultBlockState();var forbidden=new net.minecraft.world.level.BlockGetter(){public net.minecraft.world.level.block.entity.BlockEntity getBlockEntity(BlockPos p){throw new AssertionError("lighting read block entity");}public net.minecraft.world.level.block.state.BlockState getBlockState(BlockPos p){throw new AssertionError("lighting read live chunk");}public net.minecraft.world.level.material.FluidState getFluidState(BlockPos p){throw new AssertionError("lighting read fluid");}public int getHeight(){return 384;}public int getMinBuildHeight(){return -64;}};h.assertValueEqual(block.getLightBlock(state,forbidden,BlockPos.ZERO),0,"rose blocks light");h.assertTrue(block.propagatesSkylightDown(state,forbidden,BlockPos.ZERO),"rose blocks skylight");h.succeed();}
    static int dropped(GameTestHelper h,MachineEntity furnace,Item item){return h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(furnace.getBlockPos()).inflate(3,2,3),e->e.getItem().is(item)).stream().mapToInt(e->e.getItem().getCount()).sum();}
    @GameTest(template="test/platform") public static void everyFurnacePartRefusesToOpenAMenu(GameTestHelper h){var root=IntegrationGameTests.form(h);var p=thaumcraft.test.TestSupport.mockServerPlayer(h);var original=p.containerMenu;for(int y=0;y<3;y++)for(int z=-1;z<=1;z++)for(int x=-1;x<=1;x++){var m=(MachineEntity)h.getLevel().getBlockEntity(root.getBlockPos().offset(x,y,z));m.use(p,InteractionHand.MAIN_HAND);((MachineBlock)m.getBlockState().getBlock()).onWandUseOn(h.getLevel(),m.getBlockPos(),p,new ItemStack(Content.tc("wand")),Direction.EAST);h.assertTrue(p.containerMenu==original,"part opened furnace screen");}h.succeed();}
    @GameTest(template="test/platform") public static void outputsFollowTheClickedFaceEvenWhenPlayerLooksElsewhere(GameTestHelper h){var local=IntegrationGameTests.furnace(h);var p=h.makeMockPlayer(GameType.CREATIVE);p.setYRot(0);h.assertTrue(Multiblock.tryForm(h.getLevel(),h.absolutePos(local.west()),p,new ItemStack(Content.tc("wand")),Direction.WEST),"formation failed");MachineEntity root=h.getBlockEntity(local);h.assertTrue(root.facing()==Direction.WEST,"exit follows player look instead of clicked face");root.blastEmit(new ItemStack(Items.IRON_INGOT,3));var out=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(root.getBlockPos()).inflate(3),e->e.getItem().is(Items.IRON_INGOT)).getFirst();h.assertTrue(out.getX()<root.getBlockPos().getX()&&out.getDeltaMovement().x<0,"output did not eject west");var saved=root.saveWithFullMetadata(h.getLevel().registryAccess());var loaded=new MachineEntity(root.getBlockPos(),root.getBlockState());loaded.loadWithComponents(saved,h.getLevel().registryAccess());h.assertTrue(loaded.facing()==Direction.WEST,"exit lost on reload");h.succeed();}
    @GameTest(template="test/platform") public static void oldOutputBuffersAreEmittedExactlyOnce(GameTestHelper h){var m=IntegrationGameTests.form(h);m.items.setStackInSlot(1,new ItemStack(Items.GOLD_NUGGET,7));m.items.setStackInSlot(2,new ItemStack(Items.IRON_INGOT,24));for(int i=0;i<5;i++)m.blast(h.getLevel());h.assertValueEqual(dropped(h,m,Items.GOLD_NUGGET),7,"old bonus lost/duplicated");h.assertValueEqual(dropped(h,m,Items.IRON_INGOT),24,"old ingots lost/duplicated");h.assertTrue(m.items.getStackInSlot(1).isEmpty()&&m.items.getStackInSlot(2).isEmpty(),"old output remains hidden");h.succeed();}
    @GameTest(template="test/platform") public static void queuedMixedInputSurvivesReloadAndSmeltsWithoutInventory(GameTestHelper h){var m=IntegrationGameTests.form(h);m.acceptBlastInput(new ItemStack(Content.tc("native_iron_cluster")));m.acceptBlastInput(new ItemStack(Content.tc("native_gold_cluster")));var saved=m.saveWithFullMetadata(h.getLevel().registryAccess());var loaded=new MachineEntity(m.getBlockPos(),m.getBlockState());loaded.setLevel(h.getLevel());loaded.loadWithComponents(saved,h.getLevel().registryAccess());for(int i=0;i<880;i++)loaded.blast(h.getLevel());h.assertValueEqual(dropped(h,loaded,Items.IRON_INGOT),3,"queued iron lost");h.assertValueEqual(dropped(h,loaded,Items.GOLD_INGOT),3,"queued gold lost");h.assertTrue(loaded.automation()==null,"furnace still exposes former GUI inventory");h.succeed();}
    @GameTest(template="test/platform") public static void outputGoesIntoAChestAtTheExitLikeTheRelease(GameTestHelper h){var m=IntegrationGameTests.form(h);var target=m.getBlockPos().relative(m.facing(),2).above();h.getLevel().setBlockAndUpdate(target,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState());m.blastEmit(new ItemStack(Items.IRON_INGOT,3));var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)h.getLevel().getBlockEntity(target);int found=0;for(int i=0;i<chest.getContainerSize();i++)if(chest.getItem(i).is(Items.IRON_INGOT))found+=chest.getItem(i).getCount();h.assertValueEqual(found,3,"output chest did not receive ingots");h.assertValueEqual(dropped(h,m,Items.IRON_INGOT),0,"chest output was duplicated outside");h.succeed();}
    @GameTest(template="test/platform") public static void breakingFurnaceReturnsAllQueuedInput(GameTestHelper h){var m=IntegrationGameTests.form(h);m.acceptBlastInput(new ItemStack(Content.tc("native_iron_cluster"),2));m.acceptBlastInput(new ItemStack(Content.tc("native_gold_cluster"),5));h.getLevel().removeBlock(m.getBlockPos().east(),false);h.assertValueEqual(dropped(h,m,Content.tc("native_iron_cluster")),2,"working input lost during dismantling");h.assertValueEqual(dropped(h,m,Content.tc("native_gold_cluster")),5,"queued input lost or duplicated during dismantling");h.succeed();}
    @GameTest(template="test/platform") public static void survivalWandActivationDoesNotOpenScreen(GameTestHelper h){var root=IntegrationGameTests.furnace(h);var p=thaumcraft.test.TestSupport.mockServerPlayer(h);p.setGameMode(GameType.SURVIVAL);p.setPos(h.absolutePos(root.north(2)).getCenter());var wand=OrdinaryPlayTests.wand();p.setItemInHand(InteractionHand.MAIN_HAND,wand);thaumcraft.research.ResearchManager.complete(p,"INFERNALBLASTFURNACE",false);var menu=p.containerMenu;var at=h.absolutePos(root.north());var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(at),Direction.NORTH,at,false);var dry=wand.copy();for(var aspect:GemItem.PRIMALS)thaumcraft.wand.Wands.storeVis(dry,aspect,0);var spare=wand.copy();p.getInventory().setItem(10,spare);p.setItemInHand(InteractionHand.MAIN_HAND,dry);p.gameMode.useItemOn(p,h.getLevel(),dry,InteractionHand.MAIN_HAND,hit);h.assertTrue(!(h.getLevel().getBlockEntity(h.absolutePos(root)) instanceof MachineEntity),"dry held wand formed furnace using another inventory wand");p.setItemInHand(InteractionHand.MAIN_HAND,wand);int vis=thaumcraft.wand.Wands.getVis(wand,Aspect.FIRE);p.gameMode.useItemOn(p,h.getLevel(),wand,InteractionHand.MAIN_HAND,hit);h.assertTrue(vis-thaumcraft.wand.Wands.getVis(wand,Aspect.FIRE)>4000,"formation paid hundredths instead of 50 vis");h.assertValueEqual(thaumcraft.wand.Wands.getVis(spare,Aspect.FIRE),thaumcraft.wand.Wands.getMaxVis(spare),"formation drained a spare wand");h.assertTrue(h.getLevel().getBlockEntity(h.absolutePos(root)) instanceof MachineEntity,"survival right-click did not form furnace");h.assertTrue(p.containerMenu==menu,"activation opened a screen");MachineEntity m=h.getBlockEntity(root);h.assertTrue(m.facing()==Direction.NORTH,"activation ignored north face");h.succeed();}
}
